3|import { useCallback, useEffect, useMemo, useRef, useState } from "react";
4|import { useParams, useRouter } from "next/navigation";
5|import { currentMode, musicModes, parseManifest } from "@/core/music";
6|import type {
7|  MusicManifest,
8|  MusicModeId,
9|  PersistedMusicPrefs,
10|  SceneSignal,
11|} from "@/core/music";
12|import { EMOTIONS } from "@/core/types";
13|import { dispatch, startSession } from "@/core/music-session";
14|import type { MusicIntent, MusicSession, SessionView } from "@/core/music-session";
15|import { nextSceneEntry } from "@/core/reader";
16|import { DEFAULT_VOLUME, loadMusicPrefs, saveMusicPrefs } from "./music-prefs";
17|import { Player } from "./player";
18|import { THEME_KEY, TopLine } from "./folio/chrome";
19|import { initialTheme } from "./theme";
20|import { DevPanel } from "./folio/dev-panel";
21|
22|export interface SlimScene {
23|  id: string;
24|  ch: number;
25|  emotion: SceneSignal | null;
26|}
27|
28|export interface ChapterJump {
29|  ch: number;
30|  title: string;
31|  firstSceneId: string;
32|}
33|
34|const DEV_LABELS: Record<(typeof EMOTIONS)[number], string> = {
35|  calma: "calm",
36|  alegria: "joy",
37|  tristeza: "sadness",
38|  suspenso: "suspense",
39|  misterio: "mystery",
40|  aventura: "adventure",
41|  combate: "combat",
42|  asombro: "wonder",
43|};
44|
45|// Client container: bridges the music session to React state. It cues
46|// music on scene entry only, from the route id. Sub-page moves never
47|// reach the session. Params can lag a render, so the last observed id
48|// is compared before every scene entry.
49|export function Reader({
50|  scenes,
51|  chapters,
52|  bookTitle,
53|  bookAuthor,
54|  children,
55|}: {
56|  scenes: SlimScene[];
57|  chapters: ChapterJump[];
58|  bookTitle: string;
59|  bookAuthor: string;
60|  children: React.ReactNode;
61|}) {
62|  const routeParams = useParams();
63|  const router = useRouter();
64|  const param = routeParams?.sceneId;
65|  const routeSceneId = typeof param === "string" ? param : null;
66|  const [manifest, setManifest] = useState<MusicManifest | null>(null);
67|  const [view, setView] = useState<SessionView | null>(null);
68|  const [musicFailed, setMusicFailed] = useState(false);
69|  // Volume, mute, style, and Chopin mode persist in one prefs object;
70|  // the player stays a controlled view over them. State starts at the server
71|  // defaults so hydration matches, then a mount effect applies stored
72|  // prefs (parsed once) to volume, muted, and style via prefsRef.
73|  const [volume, setVolume] = useState(DEFAULT_VOLUME);
74|  const [muted, setMuted] = useState(false);
75|  const [theme, setTheme] = useState<"light" | "dark">("light");
76|  const [devOpen, setDevOpen] = useState(false);
77|  const prefsRef = useRef<PersistedMusicPrefs | null>(null);
78|  // Ref mirrors so send and persist handlers always read fresh values.
79|  const volumeRef = useRef(volume);
80|  volumeRef.current = volume;
81|  const mutedRef = useRef(muted);
82|  mutedRef.current = muted;
83|  const byId = useMemo(() => new Map(scenes.map((s) => [s.id, s.emotion])), [scenes]);
84|  const byIdRef = useRef(byId);
85|  byIdRef.current = byId;
86|  const manifestRef = useRef(manifest);
87|  manifestRef.current = manifest;
88|  const routeRef = useRef(routeSceneId);
89|  routeRef.current = routeSceneId;
90|  const sessionRef = useRef<MusicSession | null>(null);
91|  const observedRef = useRef<string | null>(null);
92|
93|  // The one bridge into the session: builds the context (clock, rng,
94|  // scene signals) and mirrors the view and a style change to state.
95|  const send = useCallback((intent: MusicIntent) => {
96|    const session = sessionRef.current;
97|    const fetched = manifestRef.current;
98|    if (!session || !fetched) return;
99|    const next = dispatch(session, intent, {
100|      manifest: fetched,
101|      signalOf: (sceneId) => byIdRef.current.get(sceneId) ?? null,
102|      routeSceneId: routeRef.current,
103|      nowSec: Date.now() / 1000,
104|      rng: Math.random,
105|    });
106|    sessionRef.current = next;
107|    if (next.view !== session.view) setView(next.view);
108|    if (next.selection !== session.selection || next.view.playlistOn !== session.view.playlistOn) {
109|      saveMusicPrefs({
110|        style: next.selection.style,
111|        volume: volumeRef.current,
112|        muted: mutedRef.current,
113|        playlist: next.view.playlistOn,
114|      });
115|    }
116|  }, []);
117|
118|  // Stored prefs load once here, after the server-matching first render.
119|  // Saves happen only on user actions below, so the defaults above never
120|  // overwrite storage before this runs. The fetch below resolves later and
121|  // reads the style through the ref.
122|  useEffect(() => {
123|    const prefs = loadMusicPrefs();
124|    prefsRef.current = prefs;
125|    if (prefs !== null) {
126|      if (prefs.volume !== null) setVolume(prefs.volume);
127|      setMuted(prefs.muted);
128|    }
129|    try {
130|      setTheme(initialTheme(window.localStorage.getItem(THEME_KEY)));
131|    } catch {
132|      // The inline script already set a theme; keep the default.
133|    }
134|    if (new URLSearchParams(window.location.search).has("dev")) setDevOpen(true);
135|  }, []);
136|
137|  useEffect(() => {
138|    let cancelled = false;
139|    fetch("/music/manifest.json")
140|      .then((res) => {
141|        if (!res.ok) throw new Error(`manifest ${res.status}`);
142|        return res.json();
143|      })
144|      .then((json: unknown) => {
145|        if (cancelled) return;
146|        const parsed = parseManifest(json);
147|        setManifest(parsed);
148|        const session = startSession(parsed, prefsRef.current);
149|        sessionRef.current = session;
150|        setView(session.view);
151|      })
152|      .catch(() => {
153|        if (!cancelled) setMusicFailed(true);
154|      });
155|    return () => {
156|      cancelled = true;
157|    };
158|  }, []);
159|
160|  // Scene entry: exactly one sceneEntered per scene id, once the manifest
161|  // lands. The first scene cues at once, so it plays on the first press.
162|  useEffect(() => {
163|    const gate = nextSceneEntry({
164|      observedId: observedRef.current,
165|      routeId: routeSceneId,
166|      manifestReady: manifest !== null,
167|    });
168|    observedRef.current = gate.nextObservedId;
169|    if (gate.shouldObserve && routeSceneId) send({ type: "sceneEntered", sceneId: routeSceneId });
170|  }, [routeSceneId, manifest, send]);
171|
172|  useEffect(() => {
173|    // Settle an expired entry dwell, or re-check the scene after a hold.
174|    const timer = window.setInterval(() => {
175|      send({ type: "tick" });
176|    }, 1000);
177|    return () => window.clearInterval(timer);
178|  }, [send]);
179|
180|  // Developer view: Shift+D outside inputs, Escape closes.
181|  useEffect(() => {
182|    const onKey = (event: KeyboardEvent) => {
183|      const target = event.target as HTMLElement | null;
184|      const typing =
185|        !!target &&
186|        (target.tagName === "INPUT" ||
187|          target.tagName === "SELECT" ||
188|          target.tagName === "TEXTAREA" ||
189|          target.isContentEditable);
190|      if (event.key === "Escape") {
191|        setDevOpen(false);
192|        return;
193|      }
194|      if (typing) return;
195|      if (event.shiftKey && (event.key === "D" || event.key === "d")) {
196|        event.preventDefault();
197|        setDevOpen((open) => !open);
198|      }
199|    };
200|    window.addEventListener("keydown", onKey);
201|    return () => window.removeEventListener("keydown", onKey);
202|  }, []);
203|
204|  function skip() {
205|    send({ type: "skip" });
206|  }
207|
208|  // Previous: back to the last played track, held like a Next. With no
209|  // history the current track restarts from zero through the replay path,
210|  // including in playlist mode.
211|  function goPrev() {
212|    send({ type: "previous" });
213|  }
214|
215|  function advanceMode(to?: MusicModeId) {
216|    send({ type: "modeAdvanced", to });
217|  }
218|
219|  function changeVolume(next: number) {
220|    setVolume(next);
221|    volumeRef.current = next;
222|    saveMusicPrefs({
223|      style: sessionRef.current?.view.style ?? null,
224|      volume: next,
225|      muted: mutedRef.current,
226|      playlist: sessionRef.current?.view.playlistOn ?? false,
227|    });
228|  }
229|
230|  function changeMuted(next: boolean) {
231|    setMuted(next);
232|    mutedRef.current = next;
233|    saveMusicPrefs({
234|      style: sessionRef.current?.view.style ?? null,
235|      volume: volumeRef.current,
236|      muted: next,
237|      playlist: sessionRef.current?.view.playlistOn ?? false,
238|    });
239|  }
240|
241|  function ended(trackId: string) {
242|    send({ type: "trackEnded", trackId });
243|  }
244|
245|  function toggleTheme() {
246|    setTheme((current) => {
247|      const next = current === "dark" ? "light" : "dark";
248|      document.documentElement.setAttribute("data-theme", next);
249|      try {
250|        window.localStorage.setItem(THEME_KEY, next);
251|      } catch {
252|        // The attribute already applies for the session.
253|      }
254|      return next;
255|    });
256|  }
257|
258|  function jumpChapter(ch: number) {
259|    const found = chapters.find((c) => c.ch === ch);
260|    if (found) router.push(`/leer/${found.firstSceneId}`);
261|  }
262|
263|  const currentId = view?.currentId ?? null;
264|  const track = manifest?.tracks.find((t) => t.id === currentId) ?? null;
265|  const empty = manifest !== null && manifest.tracks.length === 0;
266|  // Ordered music modes for the control: styles with tracks, then Chopin.
267|  const modes = manifest ? musicModes(manifest) : [];
268|  const modeCurrent = view ? currentMode(view) : null;
269|  const playlistOn = view?.playlistOn ?? false;
270|  // Previous restarts the track with no history (including the current
271|  // playlist piece), so it stays on whenever a track is cued.
272|  const canPrev = view?.canPrev ?? false;
273|  const canSkip = view?.canSkip ?? false;
274|
275|  const bookIndex = routeSceneId ? scenes.findIndex((s) => s.id === routeSceneId) : -1;
276|  const current = routeSceneId ? byId.get(routeSceneId) ?? null : null;
277|  const devBars = current
278|    ? EMOTIONS.map((id) => ({ label: DEV_LABELS[id], value: current.vector[id] ?? 0 }))
279|    : [];
280|
281|  return (
282|    <div className="folio">
283|      <TopLine
284|        bookTitle={bookTitle}
285|        author={bookAuthor}
286|        ch={routeSceneId ? (scenes[bookIndex]?.ch ?? chapters[0]?.ch ?? 1) : 1}
287|        chaptersTotal={chapters.length}
288|        chapters={chapters}
289|        onJumpChapter={jumpChapter}
290|        theme={theme}
291|        onToggleTheme={toggleTheme}
292|      />
293|      {children}
294|      <div className="band-play">
295|        {musicFailed || empty ? (
296|          <p className="player-note">The music is resting. The book is all yours.</p>
297|        ) : (
298|          <Player
299|            track={track}
300|            replayNonce={view?.replayNonce ?? 0}
301|            fadeSec={view?.fadeSec ?? 0}
302|            canPrev={canPrev}
303|            onPrev={goPrev}
304|            canSkip={canSkip}
305|            onSkip={skip}
306|            volume={volume}
307|            muted={muted}
308|            onVolumeChange={changeVolume}
309|            onMutedChange={changeMuted}
310|            modes={modes}
311|            current={modeCurrent}
312|            onAdvance={advanceMode}
313|            onEnded={ended}
314|            playlistOn={playlistOn}
315|          />
316|        )}
317|      </div>
318|      <DevPanel
319|        open={devOpen}
320|        onClose={() => setDevOpen(false)}
321|        sceneLabel={bookIndex >= 0 ? `scene ${bookIndex + 1} of ${scenes.length}` : "no scene"}
322|        bars={devBars}
323|        intensity={current?.intensity ?? null}
324|        tempo={current?.tempo ?? null}
325|        trackTitle={track?.title ?? "No track cued"}
326|      />
327|    </div>
328|  );
329|}

