  manifest: MusicManifest,
  prefs: PersistedMusicPrefs | null,
): MusicSession {
  const fields = {
    scheduler: initScheduler(),
    history: [] as string[],
    selection: resolveInitialSelection(manifest, prefs),
    fadeSec: 0,
    replayNonce: 0,
  };
